    private static Problem Seed(
        int problemNumber,
        string title,
        string url,
        string[] topics,
        string[] companies,
        Difficulty difficulty) =>
        new()
        {
            Id = ProblemId(problemNumber),
            Title = title,
            ExternalUrl = url,
            TopicTags = topics,
            Companies = companies,
            Difficulty = difficulty,
            CreatedAt = new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero)
        };

    private static Guid ProblemId(int problemNumber) =>
        problemNumber switch
        {
            // Preserve IDs from the initial migration so existing entries remain valid.
            1 => Guid.Parse("20000000-0000-0000-0000-000000000001"),
            20 => Guid.Parse("20000000-0000-0000-0000-000000000002"),
            3 => Guid.Parse("20000000-0000-0000-0000-000000000003"),
            _ => Guid.Parse($"21000000-0000-0000-0000-{problemNumber:000000000000}")
        };
}
